-- Skills dictionary, job-portal style: about 496 more skills and qualifications, 1860 more search terms,
-- each skill in an area. Generated by tools/gen-skills-migration.php from tools/skills-taxonomy.php.
-- Adds only: terms already in the dictionary (including ones added in Settings) keep their meaning.
ALTER TABLE skills_dictionary ADD COLUMN area VARCHAR(60) NULL AFTER category;
